# The size of the change from No NbS (input_0) to All NbS (input_1),
# cell by cell: 0 where they agree.
return curio_raster_calculate("subtract", [input_1, input_0], absolute=True)

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "width": {
    "step": 180
  },
  "height": {
    "step": 38
  },
  "transform": [
    {
      "calculate": "datum.scenario_name",
      "as": "Scenario"
    },
    {
      "calculate": "format(datum[\"median flood depth\"], '.2f')",
      "as": "Median flood depth (m)"
    },
    {
      "calculate": "format(datum[\"mean flood depth\"], '.2f')",
      "as": "Mean flood depth (m)"
    },
    {
      "fold": [
        "Scenario",
        "Median flood depth (m)",
        "Mean flood depth (m)"
      ],
      "as": [
        "column",
        "cell"
      ]
    }
  ],
  "encoding": {
    "x": {
      "field": "column",
      "type": "nominal",
      "sort": [
        "Scenario",
        "Median flood depth (m)",
        "Mean flood depth (m)"
      ],
      "title": null,
      "axis": {
        "orient": "top",
        "labelAngle": 0,
        "labelFontSize": 12,
        "labelFontWeight": "bold",
        "labelColor": "#333333",
        "labelPadding": 8,
        "labelLimit": 0,
        "domain": false,
        "ticks": false
      }
    },
    "y": {
      "field": "scenario_name",
      "type": "nominal",
      "sort": {
        "field": "scenario_order"
      },
      "axis": null
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#d6d9de",
        "strokeWidth": 1
      },
      "encoding": {
        "fill": {
          "condition": {
            "test": "datum.scenario_order % 2 === 1",
            "value": "#f5f6f8"
          },
          "value": "#ffffff"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.column === 'Scenario'"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 13,
        "fontWeight": "bold",
        "tooltip": true
      },
      "encoding": {
        "text": {
          "field": "cell",
          "type": "nominal"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.column !== 'Scenario'"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 13,
        "fontWeight": "normal",
        "tooltip": true
      },
      "encoding": {
        "text": {
          "field": "cell",
          "type": "nominal"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    }
  }
}
